            9'h1FB: r = 4'd0 ;  // STTASK (operand 2)
            9'h1FC: r = 4'd4 ;  // CLRTLB
            9'h1FD: r = 4'd0 ;  // CLRTLB (operand 2)
            9'h1FE: r = 4'd4 ;  // CLRTLB
            9'h1FF: r = 4'd0 ;  // CLRTLB (operand 2)
            default: r = 4'd15;    // not an instruction: nothing to say
        endcase
        op_data_bytes_first = r;
    end
endfunction

